import { cacheTag } from 'next/cache'

export type Post = { id: number; title: string }

const posts: Post[] = []
let nextId = 1

export function addPost(title: string): Post {
  const post: Post = { id: nextId++, title }
  posts.push(post)
  return post
}

export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')
  return [...posts]
}

