'use server'

import { updateTag } from 'next/cache'
import { addPost } from './posts-store'

export async function createPost(formData: FormData) {
  const title = formData.get('title')
  if (!title || typeof title !== 'string' || !title.trim()) return

  addPost(title.trim())
  updateTag('posts')
}

